// app/hifz/lib/i18n.ts — Interface-language (i18n) store + dictionaries.
//
// BUG 1 root cause (2026-11-22): Settings offered 8 interface languages
// (EN/AR/FR/ID/MS/RU/HI/UR) but NO translations existed anywhere in the
// repo — the picker only wrote `settings.language` to localStorage, and
// nothing ever read it back to render a string. Every component hardcoded
// English. So switching language changed `document.documentElement.lang`
// and `dir` only; the visible interface stayed English.
//
// Fix: real dictionaries for the core interface strings in all 8 offered
// languages, plus a tiny external store (useSyncExternalStore) so any
// client component re-renders the moment the language changes — no reload,
// no route change. English is the fallback for any key not yet translated
// (long-form help/privacy paragraphs stay English for now — see the note
// on FALLBACK below).
//
// Scope: the shell (bottom tabs, onboarding) and Settings are wired to
// this module now. `hub.*` and `coach.*` keys are translated here so the
// hub page and the recitation coach can be wired in a small follow-up pass
// by importing `useT()` — their files belong to other workers.
// No routing-based i18n (no locale URL prefixes, no middleware): the
// locale lives in the same `ili_hifz_settings_v1` document as the theme,
// so it works with the existing no-accounts, localStorage-only design.

import { useCallback, useEffect, useSyncExternalStore } from 'react';
import { loadSettings, saveSettings, type HifzSettings } from '../progress';

export type UiLocale = 'en' | 'ar' | 'ur' | 'fr' | 'id' | 'ms' | 'ru' | 'hi';
export type UiTheme = 'light' | 'dark' | 'sepia';

export const SUPPORTED_LOCALES: { code: UiLocale; name: string; rtl: boolean }[] = [
  { code: 'en', name: 'English', rtl: false },
  { code: 'ar', name: 'العربية (Arabic)', rtl: true },
  { code: 'ur', name: 'اردو (Urdu)', rtl: true },
  { code: 'fr', name: 'Français (French)', rtl: false },
  { code: 'id', name: 'Bahasa Indonesia', rtl: false },
  { code: 'ms', name: 'Bahasa Melayu (Malay)', rtl: false },
  { code: 'ru', name: 'Русский (Russian)', rtl: false },
  { code: 'hi', name: 'हिन्दी (Hindi)', rtl: false },
];

export function isSupportedLocale(code: string | undefined | null): code is UiLocale {
  return SUPPORTED_LOCALES.some((l) => l.code === code);
}

export function isRtlLocale(code: string | undefined | null): boolean {
  return code === 'ar' || code === 'ur';
}

/* ------------------------------------------------------------------ */
/*  Dictionaries — core interface strings. English is the source and   */
/*  the fallback. A key missing from a language falls back to English  */
/*  at lookup time (see `t`). Long-form help/privacy paragraphs are    */
/*  deliberately NOT translated yet — they stay English until a copy   */
/*  pass translates them; every label, heading, button and short       */
/*  description below IS translated.                                   */
/* ------------------------------------------------------------------ */

