  'diag.engineIntro': 'वही ऑन-डिवाइस पहचान मॉडल लोड करता है जो जाँचकर्ता इस्तेमाल करता है (लगभग 25 MB, एक बार डाउनलोड होकर इसी डिवाइस पर रहता है) और अल-फ़ातिहा 1:1 सुनता है। यह जाँचता है कि क्या इंजन शब्दों का अनुसरण कर सकता है — यह माइक के काम करने से अलग सवाल है। सिर्फ़ शब्दों की सटीकता; यह कभी तजवीद का फ़ैसला नहीं करता।',
