/** Merged dictionaries: every language falls back to English per key. */
const STRINGS: Record<UiLocale, Dict> = {
  en,
  ar: { ...en, ...ar },
  ur: { ...en, ...ur },
  fr: { ...en, ...fr },
  id: { ...en, ...id },
  ms: { ...en, ...ms },
  ru: { ...en, ...ru },
  hi: { ...en, ...hi },
};

/** Translate `key` in `locale` (default: the store's current locale). */
export function t(key: string, locale: UiLocale = currentLocale): string {
  return STRINGS[locale]?.[key] ?? en[key] ?? key;
}

/** All keys, for a coverage check in tests or a follow-up copy pass. */
export function uiStringKeys(): string[] {
  return Object.keys(en);
}

/* ------------------------------------------------------------------ */
/*  Store — the single live source for locale + theme in the client.   */
/*  Storage stays in progress.ts (`ili_hifz_settings_v1`); this store  */
/*  only mirrors the two prefs and notifies subscribers so the shell   */
/*  re-renders the moment a setting changes. Server snapshot is 'en' /  */
/*  'light' so hydration never mismatches; the real prefs are read in  */
/*  an effect after mount (see `useSyncUiPrefs`).                      */
/* ------------------------------------------------------------------ */

let currentLocale: UiLocale = 'en';
let currentTheme: UiTheme = 'light';
const listeners = new Set<() => void>();

function emit() {
  listeners.forEach((l) => l());
}

export function getUiLocale(): UiLocale {
  return currentLocale;
}

export function getUiTheme(): UiTheme {
  return currentTheme;
}

function subscribeUiPrefs(fn: () => void): () => void {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
}

/** Reactive current locale (server snapshot: 'en'). */
export function useUiLocale(): UiLocale {
  return useSyncExternalStore(subscribeUiPrefs, getUiLocale, () => 'en' as UiLocale);
}

/** Reactive current theme (server snapshot: 'light'). */
export function useUiTheme(): UiTheme {
  return useSyncExternalStore(subscribeUiPrefs, getUiTheme, () => 'light' as UiTheme);
}

/** Translate with the reactive current locale — re-renders on change.
 *  Memoised per locale so the returned function is stable: components can
 *  safely list it in effect/callback dependency arrays. */
export function useT(): (key: string) => string {
  const locale = useUiLocale();
  return useCallback((key: string) => t(key, locale), [locale]);
}

/** Apply a locale to <html>: lang + dir (RTL for ar/ur). */
export function applyLocaleToDocument(code: string): void {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = code;
  document.documentElement.dir = isRtlLocale(code) ? 'rtl' : 'ltr';
}

/** Apply a theme to <html data-theme> ('light' = attribute removed). */
export function applyThemeToDocument(theme: string): void {
  if (typeof document === 'undefined') return;
  if (theme === 'dark' || theme === 'sepia') {
    document.documentElement.setAttribute('data-theme', theme);
  } else {
    document.documentElement.removeAttribute('data-theme');
  }
}

function applyPrefsToDocument(locale: UiLocale, theme: UiTheme): void {
  applyLocaleToDocument(locale);
  applyThemeToDocument(theme);
}

/** Read the saved prefs from progress.ts and push them into the store
 *  + the document. Call after mount and after any out-of-band settings
 *  change (e.g. progress import). No-op on the server. */
export function syncPrefsFromStorage(): void {
  if (typeof window === 'undefined') return;
  let settings: HifzSettings;
  try {
    settings = loadSettings();
  } catch {
    return;
  }
  const locale = isSupportedLocale(settings.language) ? settings.language : 'en';
  const theme: UiTheme =
    settings.theme === 'dark' || settings.theme === 'sepia' ? settings.theme : 'light';
  const changed = locale !== currentLocale || theme !== currentTheme;
  currentLocale = locale;
  currentTheme = theme;
  applyPrefsToDocument(locale, theme);
  if (changed) emit();
}

/** Save a new interface language AND apply it immediately everywhere. */
export function setUiLocale(code: string): void {
  if (!isSupportedLocale(code)) return;
  try {
    const settings = loadSettings();
    saveSettings({ ...settings, language: code });
  } catch {
    /* storage unavailable — still apply in-memory for this session */
  }
  currentLocale = code;
  applyLocaleToDocument(code);
  emit();
}

/** Save a new theme AND apply it immediately everywhere. */
export function setUiTheme(theme: string): void {
  if (theme !== 'light' && theme !== 'dark' && theme !== 'sepia') return;
  try {
    const settings = loadSettings();
    saveSettings({ ...settings, theme });
  } catch {
    /* storage unavailable — still apply in-memory for this session */
  }
  currentTheme = theme as UiTheme;
  applyThemeToDocument(theme);
  emit();
}

/** Reset locale + theme to defaults (used after "Clear all my data"). */
export function resetUiPrefsToDefaults(): void {
  currentLocale = 'en';
  currentTheme = 'light';
  applyPrefsToDocument('en', 'light');
  emit();
}

/** Mount effect for the app shell: read the saved prefs once the client
 *  is live (avoids a hydration mismatch — the server renders 'en' /
 *  'light'), and re-sync if another tab changes the settings. Call from
 *  `BottomTabs` (which renders on `/` too, where the hifz layout does
 *  not run) and from `ThemeApplier`. */
export function useSyncUiPrefs(): void {
  useEffect(() => {
    syncPrefsFromStorage();
    const onStorage = (e: StorageEvent) => {
      if (e.key === 'ili_hifz_settings_v1') syncPrefsFromStorage();
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);
}
